// Official Pi 1.3.0 MCP, tool-search, AgentSession hooks and QuickJS runtime.
// Model responses are prescribed fixtures, not generated by a real provider.
// We enter the low-level agent after binding the session, and replace prepareRequest
// to avoid provider credential resolution. Session.prompt/auth, OAuth and real model
// choices are outside this experiment. Each mock server is a real stdio child process.
import {mkdtemp, mkdir,writeFile,readFile,rm} from 'node:fs/promises';
import assert from 'node:assert/strict';
import {tmpdir} from 'node:os';
import {join,dirname} from 'node:path';
import {fileURLToPath} from 'node:url';
import {createAgentSession,createMcpExtension,createCodemodeExtension,createToolSearchExtension,DefaultResourceLoader,SessionManager,SettingsManager,ModelRuntime} from '@earendil-works/pi-coding-agent';
const here=dirname(fileURLToPath(import.meta.url));
const usage={input:0,output:0,cacheRead:0,cacheWrite:0,totalTokens:0,cost:{input:0,output:0,cacheRead:0,cacheWrite:0,total:0}};
const model={id:'fixture',name:'Scripted',api:'fixture',provider:'fixture',baseUrl:'',reasoning:false,input:['text'],cost:usage.cost,contextWindow:128000,maxTokens:4096};
const source = await readFile(join(here, 'upgrade.js'), 'utf8');
for(const exposure of ['direct','deferred','codemode']) {
 const root=await mkdtemp(join(tmpdir(),'pi-docs-')),agentDir=join(root,'agent');await mkdir(agentDir); process.env.PI_CODING_AGENT_DIR=agentDir;
 await writeFile(join(agentDir,'mcp.json'),JSON.stringify({mcpServers:{docs:{command:process.execPath,args:[join(here,'mock-docs.mjs')],exposure,description:'Release documentation evidence'}}}));
 const hooks=[];const spy=pi=>{pi.on('tool_call',e=>{hooks.push({type:e.type,name:e.toolName,parent:!!e.parentToolCallId});});pi.on('tool_result',e=>{hooks.push({type:e.type,name:e.toolName,parent:!!e.parentToolCallId});});};
 const settingsManager=SettingsManager.create(root,agentDir);settingsManager.applyOverrides({defaultTools:['codemode','tool_search']});
 const resourceLoader=new DefaultResourceLoader({cwd:root,agentDir,settingsManager,noSkills:true,noPromptTemplates:true,noThemes:true,noContextFiles:true,extensionFactories:[createCodemodeExtension({mode:'on'}),createToolSearchExtension(),createMcpExtension(),spy]});await resourceLoader.reload();settingsManager.applyOverrides({defaultTools:['codemode','tool_search']});
 const modelRuntime=await ModelRuntime.create({authPath:join(agentDir,'auth.json'),modelsPath:null,refreshOnCreate:false,allowModelNetwork:false});
 const {session}=await createAgentSession({cwd:root,agentDir,model,modelRuntime,settingsManager,resourceLoader,sessionManager:SessionManager.inMemory()});
 const requests=[];let n=0;
 session.agent.prepareRequest=async request=>request;
 session.agent.streamFunction=async(_m,context)=>{
 const declared=new Set();for(const m of context.messages){for(const t of m.toolsAdded??[])declared.add(t.name);for(const t of m.toolsRemoved??[])declared.delete(t.name);}
 requests.push({tools:[...declared],messages:structuredClone(context.messages)});
 const call=(id,name,args)=>({type:'toolCall',id,name,arguments:args});
 let content;
 if(exposure==='codemode') content=n===0?[call('outer','codemode',{code:source})]:[{type:'text',text:'fixture finished'}];
 else if(exposure==='deferred' && n===0) content=[call('find','tool_search',{query:'release',limit:2})];
 else {const step=n-(exposure==='deferred'?1:0);content=step===0?[call('index','mcp__docs__list_releases',{})]:step===1?['1.0','1.1','1.2','missing'].map((version,i)=>call('read'+i,'mcp__docs__read_release',{version})):[{type:'text',text:'fixture finished'}];}
 n++;const message={role:'assistant',api:'fixture',provider:'fixture',model:'fixture',timestamp:0,usage,stopReason:content[0].type==='toolCall'?'toolUse':'stop',content};
 return {async *[Symbol.asyncIterator](){yield {type:'done',reason:message.stopReason,message};},async result(){return message;}};
 };
 try {await session.bindExtensions({}); for(let attempt=0;!session.getAllTools().some(t=>t.name==='mcp__docs__read_release');attempt++){if(attempt>200)throw Error('Mock MCP did not connect');await new Promise(r=>setTimeout(r,10));} await session.agent.prompt('Inspect release evidence.'); const results=session.agent.state.messages.filter(m=>m.role==='toolResult');
 const expectedRows=['1.0','1.1','1.2'].map(version=>({version,breaking:version==='1.1'?['rename retryLimit to retries']:[],evidence:`Release ${version}: verified fixture line\n`}));
 expectedRows.push({version:'missing',status:'tool_error'});
 let contentCheck;
 if(exposure==='codemode') {
   // Fixture-specific extraction: upgrade.js emits two text() items and returns one
   // JSON array. The renderer places that return value on the final text line.
   // This is not a parser for arbitrary MCP output.
   const finalText=results[0].content.filter(c=>c.type==='text').at(-1).text;
   const actualRows=JSON.parse(finalText.split('\n').at(-1));
   assert.deepEqual(actualRows,expectedRows);
   contentCheck={scope:'exact_script_return',rows:actualRows};
 } else {
   // Long results are truncated model text, so do not claim full JSON equivalence.
   // Check only these known fixture fields retained at the start of each result.
   assert(results.find(r=>r.toolCallId==='index').content.some(c=>c.text?.includes('\"versions\":[\"1.0\",\"1.1\",\"1.2\"]')));
   for(let i=0;i<3;i++) {
     const row=expectedRows[i];const r=results.find(r=>r.toolCallId==='read'+i);
     assert.equal(r.isError,false);
     const text=r.content.map(c=>c.text??'').join('');
     assert(text.includes(JSON.stringify({version:row.version,breaking:row.breaking}).slice(0,-1)), 'known version/breaking prefix absent');
     assert(text.includes(JSON.stringify(row.evidence).slice(0,-1)), 'known evidence prefix absent');
   }
   const missing=results.find(r=>r.toolCallId==='read3');assert.equal(missing.isError,true);
   assert(missing.content.some(c=>c.text?.includes('version not found')));
   contentCheck={scope:'known_retained_text_fields_only',checkedVersions:['1.0','1.1','1.2'],breakingObserved:{version:'1.1',breaking:['rename retryLimit to retries']},missing:'tool_error'};
 }
 const textChars=results.reduce((sum,r)=>sum+r.content.reduce((n,c)=>n+(c.text?.length??0),0),0);
 assert.equal(requests.length,exposure==='direct'?3:exposure==='deferred'?4:2);
 if(exposure==='codemode'){assert.equal(results.length,1);assert.equal(results[0].isError,false);assert.equal(hooks.filter(e=>e.parent).length,10);assert.match(results[0].content.map(c=>c.text??'').join(''),/tool_error/);assert(textChars<2000);}
 else {assert.equal(results.filter(r=>r.isError).length,1);assert.equal(hooks.filter(e=>e.parent).length,0);assert(textChars>60000);}
 console.log(JSON.stringify({exposure,requests:requests.length,declaredTools:requests.map(r=>r.tools),modelResultTextChars:textChars,toolResults:results.map(r=>({name:r.toolName,isError:r.isError})),hookEvents:hooks.length,nestedHookEvents:hooks.filter(e=>e.parent).length,contentCheck}));}finally{await session.extensionRunner.emit({type:'session_shutdown',reason:'exit'});session.dispose();await rm(root,{recursive:true,force:true});}
}
